pub fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    // Ensure the inputs have the same length.
    assert_eq!(
        condition.len(),
        arr.len(),
        "condition and arr must have the same length"
    );

    // Collect all values from `arr` where the corresponding
    // entry in `condition` is true.
    let mut result = Vec::new();
    for (keep, value) in condition.iter().zip(arr.into_iter()) {
        if *keep {
            result.push(value);
        }
    }

    // (Optional) sanity check: the resulting length must equal
    // the number of true values in `condition`.
    debug_assert_eq!(
        result.len(),
        condition.iter().filter(|&&c| c).count(),
        "result length must equal the number of true entries in condition"
    );

    result
}